import math

def _get_joints(agent_components):
    if isinstance(agent_components, dict):
        return agent_components.get("joints", [])
    return []

def build_agent(sandbox):
    start_x = 10.0
    start_y = 2.0  # Torso center position

    # Create a lightweight, wide torso for stability
    torso = sandbox.add_beam(
        x=start_x, y=start_y, width=1.0, height=1.0, angle=0, density=0.3
    )
    sandbox.set_material_properties(torso, friction=0.008)

    # Create two lightweight wheels at the bottom of the torso (within build zone)
    wheel_radius = 0.5
    wheel_density = 0.4
    wheel1 = sandbox.add_wheel(x=start_x - 0.5, y=1.5, radius=wheel_radius, density=wheel_density)
    wheel2 = sandbox.add_wheel(x=start_x + 0.5, y=1.5, radius=wheel_radius, density=wheel_density)
    sandbox.set_material_properties(wheel1, friction=0.008)
    sandbox.set_material_properties(wheel2, friction=0.008)

    # Connect wheels to torso at the bottom edge (y = 1.5)
    joint1 = sandbox.add_joint(
        torso, wheel1, anchor_point=(start_x - 0.5, 1.5), type='pivot'
    )
    joint2 = sandbox.add_joint(
        torso, wheel2, anchor_point=(start_x + 0.5, 1.5), type='pivot'
    )

    return {"body": torso, "joints": [joint1, joint2]}

def agent_action(sandbox, agent_body, step_count):
    joints = _get_joints(agent_body)
    # Drive wheels forward with moderate speed to avoid joint limit violations
    for j in joints:
        sandbox.set_motor(j, motor_speed=1.0, max_torque=100.0)
